INSERT INTO slides (bloco_deck, titulo, kpi_principal, bullets, fonte_rodape, status, order_index) VALUES
  ('A1', 'Brasil: Um Mercado que Nasceu para Liderar', 'Relatório Setorial 2026', '{"Primeiro relatório completo do mercado regulado com dados do 1º semestre 2026","Cobertura de 9 blocos temáticos com mais de 30 fontes primárias e oficiais","Dados via LAI, SPA/MF, Receita Federal, Serasa, iGaming Brazil e BNLData"}', 'Stellar Gaming · Born to Lead · Agosto 2026', 'approved', 1),
  ('A2', 'Sumário Executivo', '9 Blocos · 81 Slides · +30 Fontes', '{"Bloco 1: Marco Regulatório — Bloco 2: Mercado e Arrecadação","Blocos 3–4: Pagamentos, Enforcement, Perfil do Usuário e Jogo Responsável","Blocos 5–9: Mídia, Competição, Perspectivas, Contexto Global e Stellar Gaming"}', 'Stellar Gaming · Relatório Setorial 2026', 'approved', 2),
  ('A3', 'Nota Metodológica', 'Transparência como princípio', '{"Dados ATUAL (2026): base principal do relatório — sempre identificados","Dados REF (pré-2026): uso comparativo e histórico — sempre sinalizados","Fontes primárias preferidas: LAI, SPA/MF, Receita Federal, Serasa Experian"}', 'Metodologia Stellar Gaming 2026', 'approved', 3),
  ('B1.1', 'Da Proibição à Regulação: 8 Anos de Transformação', 'Jan/2025 → Mercado regulado ativo', '{"2018: Lei 13.756 autoriza apostas de quota fixa no Brasil","2023: Lei 14.790 estabelece o modelo regulatório definitivo","Jan/2025: 79 operadoras autorizadas iniciam operações — mercado regulado começa"}', 'Fonte: MF/SPA; Lei 14.790/2023; Lei 13.756/2018', 'approved', 4),
  ('B1.2', 'Lei 14.790/2023: Os Quatro Pilares da Regulação', '4 pilares estruturantes', '{"Licenciamento obrigatório via SPA/MF — outorga de R$ 30 mi por 5 anos","Tributação sobre GGR: 12% (2025) → 13% (2026) → 14% (2027) → 15% (2028)","Jogo responsável e proteção ao consumidor como obrigações legais dos operadores"}', 'Fonte: Lei 14.790/2023; LC 224/2025', 'approved', 5),
  ('B1.3', '1º Ano Regulado: Balanço Oficial SPA/MF', 'R$ 37 bi GGR em 2025', '{"25,2 milhões de CPFs cadastrados em plataformas autorizadas em 2025","R$ 9,95 bilhões em tributos federais recolhidos — acima das projeções iniciais","25 mil+ sites ilegais bloqueados em parceria com Anatel no primeiro ano"}', 'Fonte: SPA/MF — Balanço 1º Ano Regulado, jan/2026', 'approved', 6),
  ('B1.4', 'Decreto 13.033/2026: O Cerco Financeiro ao Ilegal', 'R$ 50 bi bloqueados', '{"Publicado em 18/06/2026 — primeiro mecanismo de bloqueio administrativo de contas","Encerra indefinição histórica: SPA assume responsabilidade sobre fintechs parceiras de ilegais","Receita bloqueada vai para o Fundo Nacional de Segurança Pública"}', 'Fonte: Decreto nº 13.033/2026; BNLData, jun/2026', 'approved', 7),
  ('B1.5', 'Portaria 1.766/2026: Responsabilidade Tributária Solidária', '24h para cumprir ou responder', '{"IFs e fintechs têm 24 horas para bloquear contas após notificação formal da SPA","Influenciadores que divulgam bets ilegais respondem por IR, PIS e Cofins da atividade","Primeira norma que alcança toda a cadeia financeira e de comunicação do ilegal"}', 'Fonte: Portaria MF nº 1.766/2026, 17/06/2026', 'approved', 8),
  ('B1.6', 'Prediction Markets: Brasil Entre os Primeiros a Regular', 'Resolução CMN 5.298/2026', '{"Mercados de previsão (Polymarket, Kalshi) equiparados a bets para fins regulatórios","Contratos derivativos sobre eventos políticos, esportivos e de entretenimento proibidos","Brasil se posiciona na vanguarda global — decisão antes de EUA e Europa fecharem o debate"}', 'Fonte: Resolução CMN 5.298/2026; Nota Técnica SPA 2958/2026', 'approved', 9),
  ('B1.7', 'Portaria 1.231/2024: O Marco do Jogo Responsável', 'Obrigações legais para todos os operadores', '{"Autolimitação de apostas e depósitos é obrigação — não opcional","Operadores devem enviar alertas regulares sobre tempo de jogo e valor apostado","Apostador tem direito de encerrar conta e resgatar saldo integral sem custo"}', 'Fonte: Portaria SPA/MF nº 1.231/2024', 'approved', 10),
  ('B1.8', 'Combate ao Ilegal: A Evolução do Placar', '50.000+ plataformas derrubadas', '{"Jan/2026: 25 mil sites · Abr/2026: 39 mil · Jun/2026: mais de 50 mil plataformas bloqueadas","697 contas bancárias encerradas · 172 processos instaurados contra operadores","412 processos contra influenciadores — 324 perfis e 229 publicações removidos"}', 'Fonte: SPA/MF, jan/abr/jun 2026', 'approved', 11),
  ('B1.9', 'Desenrola Adimplentes: Crédito + Autoexclusão', '800 mil fora das bets como contrapartida', '{"Lançado 29/06/2026: refinanciamento a 1,99% a.m. para trabalhadores informais","Condição: bloqueio de CPF em todas as bets por mínimo de 6 meses","Primeiro programa de crédito popular a usar autoexclusão de apostas como contrapartida"}', 'Fonte: MF/SPA; BNLData, jun/2026', 'approved', 12),
  ('B1.10', 'ECA Digital: Proteção de Menores nas Plataformas', 'Verificação de idade obrigatória', '{"Mar/2026: operadoras obrigadas a verificar maioridade com dados biométricos e documentais","Menores de 18 anos proibidos de criar contas, depositar ou realizar qualquer aposta","Responsabilidade dos operadores estendida às plataformas de pagamento integradas"}', 'Fonte: ECA Digital, mar/2026; SPA/MF', 'approved', 13),
  ('B2.1', 'GGR do 1º Semestre 2026: R$ 20,07 Bilhões', 'R$ 20,07 bi (+15,3%)', '{"+15,3% sobre o 1S/2025 (R$ 17,4 bi) — crescimento consistente, não explosão","Dados via Lei de Acesso à Informação junto à SPA/MF — fonte primária oficial","87 operadoras autorizadas e 188 marcas ativas — crescimento de 11,5% de operadoras"}', 'Fonte: BNLData / SPA-MF via LAI, ago/2026', 'approved', 14),
  ('B2.2', 'Evolução Mensal: A Copa Não Foi o Pico', 'Janeiro: R$ 4,29 bi (pico real)', '{"Jan: R$ 4,29 bi · Fev-Mar: R$ 2,8 bi · Abr-Mai: recuperação · Jun (Copa): R$ 3,34 bi","Junho teve 19 dias de Copa do Mundo e 72 partidas — foi o menor GGR do semestre","Pico em janeiro explica-se pela antecipação dos calendários esportivos ao início do ano"}', 'Fonte: BNLData / SPA-MF via LAI, ago/2026', 'approved', 15),
  ('B2.3', 'Turnover de R$ 410,85 bi e RTP de 92,2%', 'R$ 4,90 retidos de cada R$ 100 apostados', '{"R$ 410,85 bilhões apostados · R$ 377,86 bi devolvidos em prêmios no 1S/2026","Taxa de Retorno ao Apostador (RTP) de 92,2% — compatível com padrões internacionais maduros","Margem efetiva do setor: 4,9% do turnover — não os 15-20% que parte da narrativa sugere"}', 'Fonte: BNLData / SPA-MF via LAI, ago/2026', 'approved', 16),
  ('B2.4', 'Arrecadação Tributária RFB: Série Completa 2026', 'R$ 7,44 bi em 6 meses', '{"Jan: R$ 368 mi → Jun: R$ 513 mi — crescimento de 39,3% na arrecadação de quota fixa","R$ 2,48 bi de apostas de quota fixa · R$ 4,96 bi de loterias no 1S/2026","Acumulado jan-mai/2026: R$ 5,89 bi (+85,88% vs jan-mai/2025 — R$ 3,17 bi)"}', 'Fonte: Receita Federal do Brasil; BNLData, mai-ago/2026', 'approved', 17),
  ('B2.5', 'Convergência Fiscal: O Achado Metodológico', 'Diferença de apenas 0,2%', '{"RFB arrecadou R$ 2.483.210.886,95 em apostas de quota fixa no 1S/2026","SPA/MF calculou R$ 2.488.647.762,68 em destinações sociais no mesmo período","Os dois valores NÃO devem ser somados — capturam o mesmo fluxo: 12% do GGR por lei"}', 'Fonte: BNLData / SPA-MF via LAI; RFB, ago/2026', 'approved', 18),
  ('B2.6', 'Escala de Alíquotas: 2025 a 2028', 'De 12% para 15% até 2028', '{"2025: 12% sobre GGR · 2026: 13% · 2027: 14% · 2028: 15% (LC 224/2025)","Crescimento estrutural de receita independente da expansão do mercado","Impacto estimado só pelo aumento de alíquota em 2026: +R$ 850 mi (MF)"}', 'Fonte: Lei Complementar 224/2025', 'approved', 19),
  ('B2.7', 'Destinação Social: R$ 2,49 bi em 6 Meses', '12,4% do GGR para políticas públicas', '{"Esporte: R$ 870 mi · Turismo: R$ 641 mi · Segurança Pública: R$ 310 mi","Educação: R$ 228 mi · Seguridade Social: R$ 228 mi · Saúde: R$ 24 mi","SUS oferece até 100 mil teleatendimentos/mês para dependência em jogos"}', 'Fonte: BNLData / SPA-MF via LAI, ago/2026', 'approved', 20),
  ('B2.8', 'Gasto Médio por Apostador: R$ 108,27/mês', 'R$ 108,27/mês (+5%)', '{"Alta de 5,0% sobre o mesmo período de 2025 (R$ 103,10/mês)","Crescimento do gasto médio acompanhou em ritmo próximo o crescimento do GGR","Indica maturação do comportamento do apostador — não explosão de novos usuários"}', 'Fonte: BNLData / SPA-MF via LAI, ago/2026', 'approved', 21),
  ('B2.9', 'Comparativo 1S/2025 vs 1S/2026', '+15,3% GGR · +9,84% apostadores', '{"GGR: R$ 17,4 bi (1S25) → R$ 20,07 bi (1S26) · Operadoras: 78 → 87","Crescimento de base de apostadores: +2.767.762 CPFs únicos (+9,84%)","Crescimento moderado de dois dígitos baixos — mercado em maturação, não em boom"}', 'Fonte: BNLData / SPA-MF via LAI, ago/2026', 'approved', 22),
  ('B2.10', 'Market Share por Operadora: Top 10', '10 operadoras = 67% do mercado', '{"Bet365 lidera com ~17,2% do GGR · Betano (~14,8%) · Sporting (~12,3%)","Top 3 concentram 44,3% do GGR total do semestre","187 marcas no mercado — 90% do volume concentrado em menos de 20 marcas"}', 'Fonte: BNLData; iGaming Brazil, jul/2026', 'approved', 23),
  ('B2.11', 'Os 5 Milhões Fora das Plataformas', '5 milhões impedidos de apostar', '{"3 mi: beneficiários Bolsa Família/BPC proibidos por lei de acessar plataformas","1,2 mi: autoexclusão voluntária ativa · 800 mil: programa Desenrola","Restrições regulatórias ativas explicam parte do crescimento moderado do GGR"}', 'Fonte: Ministro Dario Durigan, 13/08/2026', 'approved', 24),
  ('B2.12', 'GGR 2025: O Ano de Abertura', 'R$ 37 bi — 1º ano regulado', '{"2025 foi o primeiro ano completo do mercado regulado de quota fixa no Brasil","1S/2025: R$ 17,4 bi · 2S/2025 estimado R$ 19,6 bi · Total: ~R$ 37 bi","Base comparativa para os próximos anos — mercado ainda em fase de calibragem"}', 'Fonte: SPA/MF; IBJR; BNLData jan/2026', 'approved', 25),
  ('B2.13', 'Projeção GGR 2026: Cenário Base', 'R$ 38–42 bi projetados em 2026', '{"Média mensal do 1S/2026: R$ 3,35 bi · Se mantida: R$ 40 bi no ano","Fatores de aceleração: +1 p.p. na alíquota, mais operadoras, Copa no 2S","Fatores de moderação: 5 mi bloqueados, restrições de publicidade em debate"}', 'Fonte: Projeção Stellar Gaming com base em SPA/MF via LAI, ago/2026', 'approved', 26),
  ('B2.14', 'Projeção GGR 2027-2028', 'R$ 60 bi projetados para 2028', '{"2027: alíquota 14% sobre base crescente · projeção R$ 48–55 bi de GGR","2028: alíquota 15% — patamar de maturidade · projeção R$ 55–65 bi","CAGR implícito de ~25–30% ao ano — em linha com mercados em fase de maturação"}', 'Fonte: Projeção Stellar Gaming; Goldman Sachs, mar/2026', 'approved', 27),
  ('B2.15', 'A Narrativa da ''Explosão'' e o Que os Dados Dizem', '+15,3% — crescimento, não explosão', '{"Volume apostado caiu de R$ 90 bi (jan) para R$ 56 bi (jun) — trajetória de queda contínua","Copa do Mundo não produziu o boom projetado — junho foi o menor GGR do semestre","Ausência de dados públicos é o terreno onde proliferam as narrativas mais distorcidas"}', 'Fonte: BNLData / SPA-MF via LAI, ago/2026', 'approved', 28),
  ('B3.1', 'PIX: A Infraestrutura Central do Ecossistema', 'PIX em mais de 78% dos depósitos', '{"PIX é o meio de pagamento dominante por velocidade, gratuidade e alcance nacional","Cartão de crédito representa apenas ~12% dos depósitos nas plataformas reguladas","Regulação do BCB sobre bets via PIX: monitoramento em tempo real a partir de dez/2026"}', 'Fonte: ABFintechs, abr/2026; BCB; SPA/MF', 'approved', 29),
  ('B3.2', 'KYC Obrigatório: Identidade Como Ferramenta Regulatória', '100% dos apostadores identificados', '{"CPF, biometria e geolocalização obrigatórios em todas as plataformas autorizadas","KYC integrado ao SIGAP permite rastreamento e auditoria em tempo real pela SPA","Dados do SIGAP geraram o perfil demográfico mais preciso já produzido sobre apostadores no Brasil"}', 'Fonte: SPA/MF; SIGAP; Portaria 1.231/2024', 'approved', 30),
  ('B3.3', 'Cadeia B2B: Os Bastidores do Mercado', '~135 provedores no ecossistema', '{"~70 provedores de jogos (estúdios + agregadores) · ~34 plataformas (PAMs)","~20 provedores de KYC · ~11 de odds/dados esportivos · ~7 de sportsbook","SPA-MF audiência pública jun/2026 para regulamentar certificação — norma final dez/2026"}', 'Fonte: BNLData; SPA-MF audiência pública, jun/2026', 'approved', 31),
  ('B3.4', 'Operação Conto da Sorte: A Escala do Ilegal', 'R$ 50 bi em 10 meses via 37 empresas', '{"37 empresas de um único grupo declararam R$ 400-500 mi — Receita encontrou R$ 50 bi reais","Uso de fintechs para lavagem e evasão: o caso mais emblemático do período regulado","Revelou como o mercado ilegal usa estruturas regulares como fachada financeira"}', 'Fonte: Receita Federal; BNLData, jun/2026', 'approved', 32),
  ('B3.5', 'Autoexclusão: 1,2 Milhão de Pedidos Voluntários', '1,2 mi de autoexclusões voluntárias', '{"Plataforma Centralizada: 217 mil pedidos nos primeiros 40 dias (jan/2026)","Motivo mais frequente: ''perda de controle — saúde mental'' (37-40% dos pedidos)","Sistema nacional conecta TODAS as 87 operadoras — autoexclusão em uma vale para todas"}', 'Fonte: SPA/MF, jan/2026; Ministro Durigan, ago/2026', 'approved', 33),
  ('B3.6', 'Fintechs na Mira: 24h Para Agir', 'Responsabilidade tributária solidária', '{"Portaria 1.766/2026: IFs que mantiverem contas de ilegais após notificação respondem pelos tributos","Prazo: 24 horas após notificação formal da SPA para adotar medidas restritivas","Alcança pessoa física e jurídica que divulgar publicidade de operadores sem autorização"}', 'Fonte: Portaria MF nº 1.766/2026; BNLData, jun/2026', 'approved', 34),
  ('B3.7', 'Influenciadores: Do Marketing ao Risco Fiscal', '412 processos administrativos abertos', '{"412 processos abertos pela SPA · 324 perfis removidos · 229 publicações derrubadas","A partir de jun/2026: influenciadores de bets ilegais respondem por IR e PIS/Cofins da atividade","Dilema: influenciadores de marcas reguladas seguem operando — diferenciação é chave"}', 'Fonte: SPA/MF, jan/2026; Receita Federal, jun/2026', 'approved', 35),
  ('B3.8', 'Combate ao Ilegal: A Eficácia dos Mecanismos', '41-51% das plataformas ainda são ilegais', '{"Apesar do avanço, mercado ilegal ainda representa 41-51% das plataformas ativas no Brasil","Impacto econômico estimado do ilegal: R$ 38,8 bi/ano (80% em danos à saúde)","Perfil do apostador ilegal: 69% entre 18-29 anos e 63% com renda até 2 SM"}', 'Fonte: MF/SPA coletiva jun/2026; BNLData', 'approved', 36),
  ('B4.1', '30,9 Milhões: Entendendo o Número Corretamente', '30,9 mi CPFs — 18 meses acumulados', '{"30.895.934 CPFs com cadastro ativo: período acumulado de 18 meses — NÃO um semestre","Comparação direta com 17,7 mi do 1S/2025 é metodologicamente incorreta","Crescimento real: +2.767.762 CPFs únicos no 1S/2026 sobre a base de 2025 (+9,84%)"}', 'Fonte: BNLData / SPA-MF via LAI, ago/2026', 'approved', 37),
  ('B4.2', '15,2 Milhões Ativos no 1T26: A Distinção Crítica', '15,2 mi apostadores genuinamente ativos', '{"15.186.243 CPFs com atividade real no 1T/2026 — dado do relatório oficial SIGAP","Diferença crucial: 30,9 mi registrados ≠ 15,2 mi que efetivamente apostaram","Base ativa é o dado relevante para análise de mercado — não os cadastros totais"}', 'Fonte: iGaming Brazil / SPA-MF via SIGAP, jul/2026', 'approved', 38),
  ('B4.3', 'Perfil Demográfico do Apostador Brasileiro', '68% homens · 31-40 anos dominam', '{"68,47% homens e 31,53% mulheres (1S/2026) — perfil estável em relação a 2025","Faixa 31-40 anos: 28,95% · 25-30 anos: 21,98% · Até 24 anos: 21,30%","Grupos economicamente ativos (25-50 anos) respondem por 67,63% da base total"}', 'Fonte: BNLData / SPA-MF via LAI; SIGAP, ago/2026', 'approved', 39),
  ('B4.4', 'Comportamento Multiplataforma: O Apostador Não É Fiel', '55,64% usam 2+ plataformas', '{"55,64% dos apostadores ativos operam em duas ou mais plataformas simultaneamente","17,96% usam duas · 9,89% usam três · 27,78% têm conta em quatro ou mais","Implicação estratégica: a batalha não é por cadastro — é por engajamento e preferência"}', 'Fonte: iGaming Brazil / SPA-MF via SIGAP, jul/2026', 'approved', 40),
  ('B4.5', 'Inadimplência no Brasil: O Contexto Macro', '81,7 mi inadimplentes em 2026', '{"38,1% de crescimento na inadimplência entre 2016 e 2026 — Serasa Experian","49,9% da população adulta está inadimplente · 70,5% da renda comprometida em média","Crescimento ocorreu por pandemia, juros baixos com crédito fácil e inflação — NÃO por bets"}', 'Fonte: Serasa Experian — Mapa da Inadimplência 10 Anos, fev/2026', 'approved', 41),
  ('B4.6', 'O Argumento Que os Dados Derrubam', 'Inadimplência cresceu antes das bets existirem', '{"Mercado regulado de bets existe desde jan/2025 — inadimplência crescia desde 2022","Inadimplência entre jovens (18-40 anos) CAIU no período 2016-2026","Atribuir endividamento estrutural de uma década às bets contradiz a evidência disponível"}', 'Fonte: Serasa Experian — Mapa da Inadimplência, fev/2026', 'approved', 42),
  ('B4.7', 'Saúde Mental: O Que a Ciência Diz (e Não Diz)', 'Relação bidirecional — não causal exclusiva', '{"The Lancet Public Health Commission (2024): evidência robusta de danos, mas sem causalidade exclusiva","Transtorno mental frequentemente precede o jogo — relação é bidirecional e mediada","A ciência NÃO afirma: ''o jogo causa depressão'' ou ''o jogo causa suicídio'' como relação exclusiva"}', 'Fonte: The Lancet Public Health Commission on Gambling, 2024', 'approved', 43),
  ('B4.8', 'Comparativo de Danos: Cigarro, Álcool e Apostas', 'Cigarro e álcool têm mais evidências de dano fatal', '{"Tabaco: 8,71 mi mortes globais em 2019 (GBD/The Lancet) — 2º maior risco de mortalidade","Álcool: ~3 mi mortes em 2016 — nível ''zero'' minimiza perda de saúde (The Lancet)","Apostas: danos fortíssimos em saúde mental e finanças — carga de doença ainda menor mensurada"}', 'Fonte: GBD 2019, The Lancet; Lancet Commission 2024', 'approved', 44),
  ('B4.9', 'O Gambling Disorder: A Única Exceção Científica', 'Reconhecido no DSM-5 e CID-11', '{"Gambling Disorder é reconhecido como condição primária pelo DSM-5 e CID-11","Critérios: perda de controle, apostas crescentes, abstinência, prejuízo social e financeiro","Prevalência estimada: 80 mi adultos com Gambling Disorder globalmente (The Lancet 2024)"}', 'Fonte: DSM-5; CID-11; The Lancet Public Health Commission, 2024', 'approved', 45),
  ('B4.10', 'SUS: Tratamento para Dependência em Jogos', 'Até 100 mil atendimentos/mês', '{"Programa do Ministério da Saúde: teleatendimento sigiloso via RAPS (Rede Psicossocial)","Parceria com Hospital Sírio-Libanês (Proadi-SUS) — contrato de R$ 2,9 mi","Financiado pelos R$ 24,19 mi destinados à Saúde pelos operadores no 1S/2026"}', 'Fonte: Ministério da Saúde; BNLData / SPA-MF via LAI, ago/2026', 'approved', 46),
  ('B4.11', 'Autoexclusão: A Ferramenta de Proteção em Escala', '5 mi fora das plataformas no total', '{"Total de 5 mi fora das plataformas: 1,2 mi voluntários + 3 mi Bolsa Família + 800 mi Desenrola","Plataforma centralizada cobre TODAS as 87 operadoras autorizadas automaticamente","Motivo mais frequente (37-40%): ''perda de controle sobre o jogo — saúde mental''"}', 'Fonte: SPA/MF; Ministro Durigan, ago/2026', 'approved', 47),
  ('B4.12', 'Jogo Responsável: O Que a Regulação Exige', '8 obrigações legais por operador', '{"Autolimitação de apostas e depósitos · Alertas regulares sobre tempo e valor","SAC obrigatório com atendimento especializado · Material educativo sobre dependência","Direito do apostador: encerrar conta + resgatar saldo integral + não ter dados cedidos"}', 'Fonte: Portaria SPA/MF 1.231/2024', 'approved', 48),
  ('B5.1', 'Bets no Futebol Brasileiro: A Escala do Fenômeno', '20 dos 26 clubes da Série A', '{"20 das 26 equipes da Série A 2026 têm bets como patrocinadores máster","Bets superaram cerveja como principal categoria de patrocinador do futebol brasileiro","Naming rights de estádios e cotas de transmissão: próximos campos de disputa"}', 'Fonte: CBF; iGaming Brazil, 2026', 'approved', 49),
  ('B5.2', 'Copa do Mundo 2026: Primeiro Mundial com Mercado Regulado', 'Primeiro Mundial com bets legais no Brasil', '{"Copa com sede nos EUA, Canadá e México — jogos em fuso favorável ao apostador brasileiro","Operadoras investiram fortemente em marketing pré-Copa — antecipação explica pico de jan","Resultado: junho foi o menor GGR do semestre — Copa rearranjou, não expandiu o mercado"}', 'Fonte: BNLData / SPA-MF via LAI, ago/2026', 'approved', 50),
  ('B5.3', 'Publicidade: O Próximo Campo de Batalha Regulatória', '230+ PLs sobre publicidade de bets no Congresso', '{"Ministro Durigan (29/06): novas restrições via ato administrativo ou MP em preparação","Proposta de tratamento similar a álcool e cigarro: advertências obrigatórias nos anúncios","CONAR publicou novas diretrizes jan/2026 — influenciadores com 25+ anos para promover apostas"}', 'Fonte: BNLData; Poder360; CONAR jan/2026', 'approved', 51),
  ('B5.4', 'CazéTV e a Investigação da Senacon', 'Investigação por inserção em transmissões da Copa', '{"Senacon abriu procedimento contra CazéTV por possíveis práticas abusivas durante Copa 2026","Questão: inserção de apostas e bets durante transmissões ao vivo para audiências amplas","Caso emblemático para o debate sobre publicidade contextual e responsabilidade das plataformas"}', 'Fonte: Senacon; BNLData, jun/2026', 'approved', 52),
